--
-- Estructura de tabla para la tabla `movil_proyecto`
--

CREATE TABLE `movil_proyecto` (
  `id_movil_proyecto` int NOT NULL,
  `id_persona` int NOT NULL COMMENT 'FK a logeo (usuario que registra)',
  `nombre_proyecto` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nombre del proyecto',
  `id_empresa` int NOT NULL COMMENT 'FK a empresa',
  `id_bodega` int NOT NULL COMMENT 'FK a bodega',
  `id_reserva` int NOT NULL COMMENT 'FK a tipo de reserva',
  `id_responsable` int NOT NULL COMMENT 'FK a personal (responsable físico)',
  `descripcion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Descripción del proyecto',
  `fecha_registro` date NOT NULL COMMENT 'Fecha de registro',
  `estado` enum('ACTIVO','INACTIVO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVO',
  `puede_subproyectos` tinyint(1) DEFAULT '1' COMMENT 'Indica si puede tener subproyectos',
  `proyecto_padre_id` int DEFAULT NULL COMMENT 'FK a movil_proyecto si es subproyecto'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Proyectos que pueden tener subproyectos (Móvil con Proyecto)';

