--
-- Estructura de tabla para la tabla `orden_pedido`
--

CREATE TABLE `orden_pedido` (
  `id_orden_pedido` int NOT NULL COMMENT 'ID único de la orden de pedido',
  `correlativo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Correlativo único (ej: OP-0001)',
  `id_empresa` int NOT NULL COMMENT 'FK: Empresa que realiza el pedido',
  `id_proyecto` int NOT NULL COMMENT 'FK: Proyecto al que pertenece el pedido',
  `fecha_pedido` date NOT NULL COMMENT 'Fecha del pedido',
  `observacion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Observación general del pedido',
  `estado` enum('PENDIENTE','APROBADO','RECHAZADO','EN_PROCESO','COMPLETADO','CANCELADO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PENDIENTE' COMMENT 'Estado de la orden',
  `estado_compra` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'SIN_PROCESAR',
  `fecha_requerida` date DEFAULT NULL COMMENT 'Fecha en la que se requieren los productos',
  `usuario_solicitante` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que solicita',
  `usuario_aprobador` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que aprueba',
  `fecha_aprobacion` datetime DEFAULT NULL COMMENT 'Fecha de aprobación',
  `usuario_creacion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que creó el registro',
  `fecha_creacion` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Fecha de creación',
  `usuario_modificacion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Usuario que modificó',
  `fecha_modificacion` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT 'Fecha de modificación'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tabla de órdenes de pedido (cabecera)';

